import {configSection,today,productionStage} from '../core/business.js?v=20261104-v10b';
export function install(ctx){
 const stageFor=q=>configSection(ctx.settings,'production').stages.find(s=>s.key===q.stage)||{key:q.stage,label:q.stage,color:'#64748b'};
 const moneyState=q=>{const f=ctx.orderFinance?.find(f=>f.quote_id===q.id);return {paid:Number(f?.paid||0),pending:Number(f?.pending??q.total)}};
 function stageBadge(q){const s=stageFor(q);return `<span class="stage-badge" style="--stage-color:${s.color}">${ctx.esc(s.label)}</span>`}
 function workflowPage(){const stages=configSection(ctx.settings,'production').stages;ctx.shell(`${ctx.head('Cada pedido, no seu lugar.','Acompanhe aprovação, entrada, produção, entrega e saldo final.','quote','Novo orçamento')}<div class="toolbar"><div class="segmented"><button class="active" id="view-board">Quadro</button><button id="view-list">Lista</button></div><input id="order-search" type="search" aria-label="Buscar pedido" placeholder="Buscar cliente ou número…"><label class="inline-check"><input type="checkbox" id="show-closed"> Mostrar finalizados e cancelados</label><button class="secondary small" id="refresh-board">${ctx.icon('refresh')} Atualizar</button></div><div id="order-board"></div><p class="muted helper">Arraste um cartão para uma etapa ou abra o pedido para alterar o andamento. Nenhum pagamento é registrado apenas por mover o cartão.</p>`);let mode='board';
  function draw(){const search=ctx.$('#order-search').value.toLowerCase(),closed=ctx.$('#show-closed').checked;const list=ctx.quotes.filter(q=>(closed||!['completed','cancelled'].includes(q.stage))&&(String(q.number)+' '+q.client_snapshot.name).toLowerCase().includes(search));const activeStages=stages.filter(s=>(s.enabled!==false||list.some(q=>q.stage===s.key))&&(closed||!['completed','cancelled'].includes(s.key)));const card=q=>{const f=moneyState(q);return `<article class="order-card" data-order="${q.id}" draggable="${ctx.can('workflow','edit')}" tabindex="0"><div class="card-top"><span>#${String(q.number).padStart(4,'0')}</span><span class="technique">${ctx.esc(q.production?.technique||'A definir')}</span></div><h3>${ctx.esc(q.client_snapshot.name)}</h3><p>${ctx.money(q.total)}</p><div class="order-card-bottom"><span class="${q.delivery_date&&q.delivery_date<today()?'overdue':''}">${ctx.icon('calendar')} ${q.delivery_date?ctx.date(q.delivery_date):'Sem prazo definido'}</span><span class="payment-chip ${f.pending<=0?'paid':''}">${f.pending<=0?'Pago':f.paid>0?'Parcial':'A receber'}</span></div></article>`};
   ctx.$('#order-board').innerHTML=mode==='board'?`<div class="kanban">${activeStages.map(s=>{const orders=list.filter(q=>q.stage===s.key);return `<section class="kanban-column" data-stage="${s.key}" style="--stage-color:${s.color}"><header><span class="stage-dot"></span><h2>${ctx.esc(s.label)}</h2><b>${orders.length}</b></header><div class="column-total">${ctx.money(orders.reduce((n,q)=>n+Number(q.total),0))}</div><div class="kanban-cards">${orders.map(card).join('')||'<div class="column-empty">Nenhum pedido nesta etapa</div>'}</div></section>`}).join('')}</div>`:`<section class="panel"><div class="table-wrap"><table><thead><tr><th>Pedido</th><th>Cliente</th><th>Etapa</th><th>Entrega</th><th>Total</th><th>Recebido</th><th>Saldo</th><th></th></tr></thead><tbody>${list.map(q=>{const f=moneyState(q);return `<tr><td>#${q.number}</td><td>${ctx.esc(q.client_snapshot.name)}</td><td>${stageBadge(q)}</td><td>${q.delivery_date?ctx.date(q.delivery_date):'—'}</td><td>${ctx.money(q.total)}</td><td>${ctx.money(f.paid)}</td><td>${ctx.money(f.pending)}</td><td><button class="secondary small" data-order="${q.id}">Abrir pedido</button></td></tr>`}).join('')}</tbody></table></div></section>`;
   document.querySelectorAll('[data-order]').forEach(el=>{el.onclick=()=>orderDialog(el.dataset.order);el.onkeydown=e=>{if(e.key==='Enter')orderDialog(el.dataset.order)};el.ondragstart=e=>{e.dataTransfer.setData('text/plain',el.dataset.order);el.classList.add('dragging')};el.ondragend=()=>el.classList.remove('dragging')});document.querySelectorAll('[data-stage]').forEach(el=>{el.ondragover=e=>{if(ctx.can('workflow','edit')){e.preventDefault();el.classList.add('drop-target')}};el.ondragleave=()=>el.classList.remove('drop-target');el.ondrop=e=>{e.preventDefault();el.classList.remove('drop-target');const id=e.dataTransfer.getData('text/plain');if(ctx.quotes.some(q=>q.id===id))orderDialog(id,el.dataset.stage)}});
  }
  draw();ctx.$('#order-search').oninput=draw;ctx.$('#show-closed').onchange=draw;for(const [id,m]of [['view-board','board'],['view-list','list']])ctx.$('#'+id).onclick=()=>{mode=m;ctx.$('#view-board').classList.toggle('active',m==='board');ctx.$('#view-list').classList.toggle('active',m==='list');draw()};ctx.$('#refresh-board').onclick=async()=>{try{await ctx.load();workflowPage()}catch(e){ctx.toast(e.message)}};
 }
 async function orderDialog(id,stage){const q=ctx.quotes.find(q=>q.id===id);if(!q)return;const cfg=configSection(ctx.settings,'production'),f=moneyState(q),prod=q.production||{},editable=ctx.can('workflow','edit');const d=ctx.modal('Pedido #'+String(q.number).padStart(4,'0'),`<div class="order-detail-top"><div><h3>${ctx.esc(q.client_snapshot.name)}</h3>${stageBadge(q)}</div><div><strong>${ctx.money(q.total)}</strong><small>Recebido ${ctx.money(f.paid)} · Saldo ${ctx.money(f.pending)}</small></div></div><form id="order-form"><div class="grid2"><label class="field">Etapa do pedido<select name="stage" ${!editable?'disabled':''}>${cfg.stages.filter(s=>s.enabled!==false||s.key===q.stage).map(s=>`<option value="${s.key}" ${(stage||q.stage)===s.key?'selected':''}>${ctx.esc(s.label)}</option>`).join('')}</select></label>${ctx.field('Entrega prevista','delivery_date','date',q.delivery_date||'',!editable?'disabled':'')}<label class="field">Personalização<select name="technique" ${!editable?'disabled':''}><option value="">A definir</option>${cfg.techniques.map(t=>`<option ${prod.technique===t?'selected':''}>${ctx.esc(t)}</option>`).join('')}</select></label><label class="inline-check"><input type="checkbox" name="art_approved" ${prod.art_approved?'checked':''} ${!editable?'disabled':''}> Arte aprovada pelo cliente</label>${ctx.field('Aprovações do cliente concluídas em','approvals_date','date',prod.approvals_date||'',!editable?'disabled':'')}<p class="note">Informe essa data somente quando o cliente concluir as aprovações. O prazo é estimado em dias úteis até a entrega prevista.</p><label class="field span2">Instruções de produção<textarea name="specifications" maxlength="10000" ${!editable?'disabled':''}>${ctx.esc(prod.specifications||'')}</textarea></label><label class="field span2">Registro desta alteração / motivo<textarea name="note" maxlength="3000" ${!editable?'disabled':''}></textarea></label></div><p class="note">Mover uma etapa não confirma recebimentos. Cancelar ou suspender um pedido também não apaga o histórico financeiro; revise as parcelas e eventuais estornos no Financeiro.</p><p id="order-error" role="alert"></p><div class="form-actions">${ctx.can('quotes','view')?'<button class="secondary" type="button" id="open-proposal">Ver orçamento / PDF</button>':''}${ctx.can('finance','create')?'<button class="secondary" type="button" id="prepare-order">Gerar parcelas</button>':''}${ctx.can('receipts')?'<button class="secondary" type="button" id="order-receipts">Recibos</button>':''}${editable?'<button class="primary" type="submit">Salvar andamento</button>':''}</div></form><section class="history"><h3>Histórico do pedido</h3><div id="order-history">Carregando…</div></section>`,{wide:true});
  d.querySelector('#order-receipts')?.addEventListener('click',()=>{d.close();ctx.receiptListDialog(id)});d.querySelector('#open-proposal')?.addEventListener('click',()=>{d.close();ctx.openQuote(id)});d.querySelector('#prepare-order')?.addEventListener('click',()=>ctx.receivableDialog(id));
  d.querySelector('#order-form').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;const data=new FormData(e.target);try{const change={p_quote:id,p_stage:data.get('stage'),p_delivery:data.get('delivery_date')||null,p_production:{...prod,technique:data.get('technique'),specifications:data.get('specifications'),art_approved:data.has('art_approved'),approvals_date:data.get('approvals_date')||null},p_note:data.get('note'),p_expected:q.updated_at};if(change.p_stage==='completed'&&Number(q.total)>0&&configSection(ctx.settings,'budget').receipt_auto_on_completion&&ctx.can('receipts','create')){const receipt=await ctx.rpc('complete_order_with_receipt',{...change,p_request:crypto.randomUUID()});await ctx.load();d.close();await ctx.showReceipt(receipt);ctx.toast('Pedido finalizado e recibo de quitação emitido.');return}if(Number(q.total)>0&&productionStage(change.p_stage,cfg.stages)&&!productionStage(q.stage,cfg.stages)&&configSection(ctx.settings,'budget').receipt_auto_on_production&&ctx.can('receipts','create')){d.close();ctx.productionReceiptDialog(id,change);return}await ctx.rpc('update_order',change);await ctx.load();d.close();ctx.render('workflow');ctx.toast('Andamento atualizado e registrado no histórico.')}catch(err){d.querySelector('#order-error').textContent=err.message;b.disabled=false}};
  try{const events=await ctx.api('/rest/v1/quote_events?quote_id=eq.'+id+'&select=*&order=created_at.desc');d.querySelector('#order-history').innerHTML=events.length?events.map(ev=>`<div class="history-row"><span class="stage-dot" style="--stage-color:#94a3b8"></span><div><strong>${ctx.esc(cfg.stages.find(s=>s.key===ev.next_stage)?.label||ev.next_stage)}</strong><p>${ctx.esc(ev.note||'Etapa atualizada')}</p><small>${new Date(ev.created_at).toLocaleString('pt-BR')}</small></div></div>`).join(''):'<p class="muted">Pedido criado em '+ctx.date(q.created_at)+'. Nenhuma mudança de etapa registrada.</p>'}catch(e){d.querySelector('#order-history').textContent=e.message}
 }
 Object.assign(ctx,{workflowPage,orderDialog,stageBadge,moneyState});
}
